cat << 'EOF' > /app/generate_report.py
import pandas as pd
import numpy as np
import matplotlib.pyplot as plt
import seaborn as sns
import base64
from io import BytesIO
import json

# Set plot style
sns.set_theme(style="whitegrid")
plt.rcParams['font.family'] = 'sans-serif'

# 1. Load Data
df = pd.read_csv('/app/benchmark/data.csv')

# 2. Compute KPIs
avg_hsc = df['HSC_Result'].mean()
exc_rate = (df['HSC_Result'] >= 4.5).mean() * 100
risk_rate = (df['HSC_Result'] < 3.0).mean() * 100
gpa_delta = df['HSC_Result'].mean() - df['Previous_GPA'].mean()
att_corr = df['Attendance'].corr(df['HSC_Result'])

# Function to encode plot to base64
def get_base64_plot(fig):
    buf = BytesIO()
    fig.savefig(buf, format='png', bbox_inches='tight', dpi=150)
    plt.close(fig)
    return base64.b64encode(buf.getvalue()).decode('utf-8')

# 3. Generate Visualizations

# V1: Demographics
fig, axes = plt.subplots(1, 3, figsize=(15, 5))
df['Gender'].value_counts().plot.pie(ax=axes[0], autopct='%1.1f%%', colors=['#4c72b0', '#dd8452'])
axes[0].set_title('Gender Distribution')
axes[0].set_ylabel('')

df['School_Type'].value_counts().plot.pie(ax=axes[1], autopct='%1.1f%%', colors=['#55a868', '#c44e52'])
axes[1].set_title('School Type Distribution')
axes[1].set_ylabel('')

sns.countplot(y='District', data=df, order=df['District'].value_counts().index, ax=axes[2], palette='viridis')
axes[2].set_title('Students per District')
axes[2].set_xlabel('Count')
axes[2].set_ylabel('')
plt.tight_layout()
v1_demo = get_base64_plot(fig)

# V2: Academic Performance
fig, ax = plt.subplots(figsize=(10, 5))
sns.kdeplot(df['Previous_GPA'], label='Previous GPA', fill=True, ax=ax)
sns.kdeplot(df['SSC_Result'], label='SSC Result', fill=True, ax=ax)
sns.kdeplot(df['HSC_Result'], label='HSC Result', fill=True, ax=ax)
ax.set_title('Distribution of Academic Performance')
ax.set_xlabel('GPA')
ax.set_xlim(0, 5)
ax.legend()
plt.tight_layout()
v2_acad = get_base64_plot(fig)

# V3: Socio-Economic Impact
fig, axes = plt.subplots(1, 3, figsize=(18, 5))
sns.boxplot(x='Parent_Education', y='HSC_Result', data=df, ax=axes[0], 
            order=['Primary', 'Secondary', 'Higher Secondary', 'Graduate'], palette='Blues')
axes[0].set_title('HSC Result by Parent Education')
axes[0].tick_params(axis='x', rotation=45)

# For Income, let's create bins
df['Income_Group'] = pd.qcut(df['Family_Income_BDT'], q=4, labels=['Low', 'Lower-Mid', 'Upper-Mid', 'High'])
sns.boxplot(x='Income_Group', y='HSC_Result', data=df, ax=axes[1], palette='Greens')
axes[1].set_title('HSC Result by Family Income Quartile')

sns.boxplot(x='Internet_Access', y='HSC_Result', data=df, ax=axes[2], palette='Oranges')
axes[2].set_title('HSC Result by Internet Access')
plt.tight_layout()
v3_socio = get_base64_plot(fig)

# V4: Study Behavior & Attendance
fig, axes = plt.subplots(1, 2, figsize=(14, 5))
sns.scatterplot(x='Attendance', y='HSC_Result', data=df, alpha=0.5, ax=axes[0])
sns.regplot(x='Attendance', y='HSC_Result', data=df, scatter=False, color='red', ax=axes[0])
axes[0].set_title('Attendance vs HSC Result')

sns.scatterplot(x='Study_Hours_per_Week', y='HSC_Result', data=df, alpha=0.5, ax=axes[1])
sns.regplot(x='Study_Hours_per_Week', y='HSC_Result', data=df, scatter=False, color='red', ax=axes[1])
axes[1].set_title('Study Hours per Week vs HSC Result')
plt.tight_layout()
v4_study = get_base64_plot(fig)

# V5: Regional Disparities Heatmap
fig, ax = plt.subplots(figsize=(10, 6))
pivot_district = df.pivot_table(values='HSC_Result', index='District', columns='School_Type', aggfunc='mean')
sns.heatmap(pivot_district, annot=True, cmap='YlGnBu', fmt=".2f", ax=ax)
ax.set_title('Average HSC Result by District and School Type')
plt.tight_layout()
v5_region = get_base64_plot(fig)

# Calculate specific stats for the report text
parent_grad_avg = df[df['Parent_Education'] == 'Graduate']['HSC_Result'].mean()
parent_prim_avg = df[df['Parent_Education'] == 'Primary']['HSC_Result'].mean()
internet_yes_avg = df[df['Internet_Access'] == 'Yes']['HSC_Result'].mean()
internet_no_avg = df[df['Internet_Access'] == 'No']['HSC_Result'].mean()
income_high_avg = df[df['Income_Group'] == 'High']['HSC_Result'].mean()
income_low_avg = df[df['Income_Group'] == 'Low']['HSC_Result'].mean()

# 4. Generate HTML
html = f"""<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Student Performance Analytics Report - Bangladesh</title>
    <style>
        :root {{
            --primary: #2C3E50;
            --secondary: #34495E;
            --accent: #3498DB;
            --light: #ECF0F1;
            --success: #27AE60;
            --warning: #F39C12;
            --danger: #E74C3C;
        }}
        body {{
            font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;
            line-height: 1.6;
            color: #333;
            background-color: #f8f9fa;
            margin: 0;
            padding: 0;
        }}
        .container {{
            max-width: 1200px;
            margin: 0 auto;
            padding: 2rem;
            background-color: #fff;
            box-shadow: 0 0 20px rgba(0,0,0,0.05);
        }}
        header {{
            text-align: center;
            margin-bottom: 3rem;
            padding-bottom: 2rem;
            border-bottom: 2px solid var(--light);
        }}
        h1 {{
            color: var(--primary);
            font-size: 2.5rem;
            margin-bottom: 0.5rem;
        }}
        .subtitle {{
            color: #7f8c8d;
            font-size: 1.2rem;
            font-weight: 300;
        }}
        .kpi-container {{
            display: flex;
            justify-content: space-between;
            flex-wrap: wrap;
            gap: 1.5rem;
            margin-bottom: 3rem;
        }}
        .kpi-card {{
            flex: 1;
            min-width: 200px;
            background: #fff;
            padding: 1.5rem;
            border-radius: 8px;
            box-shadow: 0 4px 6px rgba(0,0,0,0.1);
            border-top: 4px solid var(--accent);
            text-align: center;
        }}
        .kpi-card.success {{ border-top-color: var(--success); }}
        .kpi-card.warning {{ border-top-color: var(--warning); }}
        .kpi-card.danger {{ border-top-color: var(--danger); }}
        .kpi-value {{
            font-size: 2.5rem;
            font-weight: bold;
            color: var(--primary);
            margin: 0.5rem 0;
        }}
        .kpi-label {{
            font-size: 0.9rem;
            color: #7f8c8d;
            text-transform: uppercase;
            letter-spacing: 1px;
        }}
        section {{
            margin-bottom: 4rem;
        }}
        h2 {{
            color: var(--secondary);
            border-bottom: 2px solid var(--accent);
            padding-bottom: 0.5rem;
            margin-bottom: 1.5rem;
        }}
        .chart-container {{
            margin: 2rem 0;
            text-align: center;
            background: #fff;
            padding: 1rem;
            border-radius: 8px;
            border: 1px solid var(--light);
        }}
        .chart-container img {{
            max-width: 100%;
            height: auto;
        }}
        .insights {{
            background-color: var(--light);
            padding: 1.5rem;
            border-left: 4px solid var(--accent);
            border-radius: 0 8px 8px 0;
            margin-top: 1.5rem;
        }}
        .insights ul {{
            margin: 0;
            padding-left: 1.5rem;
        }}
        .insights li {{
            margin-bottom: 0.5rem;
        }}
    </style>
</head>
<body>
    <div class="container">
        <header>
            <h1>Student Performance Analytics Report</h1>
            <div class="subtitle">Factors Influencing Academic Outcomes in Bangladesh</div>
            <p><strong>Audience:</strong> Education Policy Analysts & School Administrators</p>
        </header>

        <!-- KPI Executive Summary -->
        <div class="kpi-container">
            <div class="kpi-card">
                <div class="kpi-label">Average HSC Result</div>
                <div class="kpi-value">{avg_hsc:.2f}</div>
                <div style="font-size: 0.8rem; color: #7f8c8d;">Out of 5.0</div>
            </div>
            <div class="kpi-card success">
                <div class="kpi-label">Excellent Performance</div>
                <div class="kpi-value">{exc_rate:.1f}%</div>
                <div style="font-size: 0.8rem; color: #7f8c8d;">GPA ≥ 4.5</div>
            </div>
            <div class="kpi-card danger">
                <div class="kpi-label">At-Risk Students</div>
                <div class="kpi-value">{risk_rate:.1f}%</div>
                <div style="font-size: 0.8rem; color: #7f8c8d;">GPA &lt; 3.0</div>
            </div>
            <div class="kpi-card {'success' if gpa_delta > 0 else 'warning'}">
                <div class="kpi-label">GPA Progression Delta</div>
                <div class="kpi-value">{gpa_delta:+.2f}</div>
                <div style="font-size: 0.8rem; color: #7f8c8d;">Avg HSC - Prev GPA</div>
            </div>
            <div class="kpi-card">
                <div class="kpi-label">Attendance-Perf Correlation</div>
                <div class="kpi-value">{att_corr:.2f}</div>
                <div style="font-size: 0.8rem; color: #7f8c8d;">Pearson r</div>
            </div>
        </div>

        <section id="demographic-overview">
            <h2>Student Demographic Overview</h2>
            <p>The analyzed dataset consists of {len(df)} students across multiple districts in Bangladesh. Understanding this baseline is crucial for contextualizing the subsequent performance analyses.</p>
            <div class="chart-container">
                <img src="data:image/png;base64,{v1_demo}" alt="Demographics Charts">
            </div>
        </section>

        <section id="academic-performance-analysis">
            <h2>Academic Performance Analysis</h2>
            <p>The distribution of grades reveals a concerning trend of academic stagnation. The GPA Progression Delta of <strong>{gpa_delta:+.2f}</strong> indicates that, on average, students are not improving significantly between their previous evaluations and their HSC exams.</p>
            <div class="chart-container">
                <img src="data:image/png;base64,{v2_acad}" alt="Academic Performance Distribution">
            </div>
            <div class="insights">
                <strong>Key Observations:</strong>
                <ul>
                    <li>The overall HSC pass rate (assuming GPA ≥ 2.0 pass mark) is overwhelmingly high, but the proportion of students attaining "Excellent" marks is {exc_rate:.1f}%.</li>
                    <li>The density plot illustrates a shift in distribution shapes across previous GPA, SSC, and HSC, highlighting where performance bottlenecks occur.</li>
                </ul>
            </div>
        </section>

        <section id="socioeconomic-impact">
            <h2>Socio-Economic Factors and Their Impact on Performance (Critical Analysis)</h2>
            <p>This section outlines the most significant drivers of educational inequality. We analyze how structurally embedded socio-economic factors affect HSC outcomes.</p>
            <div class="chart-container">
                <img src="data:image/png;base64,{v3_socio}" alt="Socio-Economic Impact Charts">
            </div>
            <div class="insights">
                <strong>Crucial Findings for Policy Analysts:</strong>
                <ul>
                    <li><strong>Parental Education Effect:</strong> Students whose parents hold a Graduate degree score on average <strong>{parent_grad_avg:.2f}</strong> in their HSC, compared to <strong>{parent_prim_avg:.2f}</strong> for students whose parents only have Primary education. This constitutes a systemic advantage.</li>
                    <li><strong>Income Disparity:</strong> The top 25% income quartile averages an HSC score of <strong>{income_high_avg:.2f}</strong>, compared to <strong>{income_low_avg:.2f}</strong> in the bottom quartile.</li>
                    <li><strong>Digital Divide:</strong> Internet access provides a clear academic edge, with connected students averaging <strong>{internet_yes_avg:.2f}</strong> versus <strong>{internet_no_avg:.2f}</strong> for those without access.</li>
                </ul>
            </div>
        </section>

        <section id="study-behavior-attendance">
            <h2>Study Behavior and Attendance Patterns</h2>
            <p>Student engagement, measured through attendance and self-directed study hours, shows a distinct relationship with final outcomes.</p>
            <div class="chart-container">
                <img src="data:image/png;base64,{v4_study}" alt="Study Behavior Charts">
            </div>
            <div class="insights">
                <strong>Behavioral Insights:</strong>
                <ul>
                    <li>Attendance shows a positive correlation (<strong>r = {att_corr:.2f}</strong>) with HSC results, confirming that physical presence in classrooms remains a foundational element of success.</li>
                    <li>Self-directed study hours also display a positive trend line, though variance is high, suggesting the <em>quality</em> of study hours may be as important as the quantity.</li>
                </ul>
            </div>
        </section>

        <section id="regional-disparities">
            <h2>Regional Performance Disparities</h2>
            <p>Geographic and institutional factors significantly alter the educational landscape. The heatmap below breaks down the average HSC result by district and school type.</p>
            <div class="chart-container">
                <img src="data:image/png;base64,{v5_region}" alt="Regional Disparities Heatmap">
            </div>
            <div class="insights">
                <strong>Geographic Inequalities:</strong>
                <ul>
                    <li>The data visually confirms the presence of educational hubs. Distinct variations exist between districts.</li>
                    <li>Public vs. Private school performance differs systematically across regions, indicating uneven resource distribution and institutional quality.</li>
                </ul>
            </div>
        </section>

        <section id="recommendations">
            <h2>Key Findings and Policy Recommendations</h2>
            <p>Based on the data presented, the following actionable recommendations are proposed to address educational disparities in Bangladesh:</p>
            <div class="insights" style="border-left-color: var(--success);">
                <ul>
                    <li><strong>Targeted Intervention for At-Risk Demographics:</strong> Implement resource-allocation policies prioritizing students from lower-income families and those whose parents have only primary education, as they show a measurable gap in performance (a difference of {parent_grad_avg - parent_prim_avg:.2f} GPA points based on parent education).</li>
                    <li><strong>Bridging the Digital Divide:</strong> With internet access correlating with higher HSC results ({internet_yes_avg:.2f} vs {internet_no_avg:.2f}), policy should focus on expanding digital infrastructure and providing subsidized internet access to rural and lower-income students.</li>
                    <li><strong>Regional Equalization Programs:</strong> The district-level heatmap shows clear disparities. Funding should be re-routed to underperforming districts and public schools lagging behind their private counterparts in those specific areas.</li>
                    <li><strong>Addressing the GPA Stagnation:</strong> A GPA Progression Delta of {gpa_delta:+.2f} indicates structural bottlenecks between SSC and HSC levels. Curriculum review and targeted tutoring programs should be established to support students transitioning to higher secondary education.</li>
                </ul>
            </div>
        </section>
    </div>
</body>
</html>"""

with open('/app/output/final_report.html', 'w') as f:
    f.write(html)

print("HTML report successfully generated at /app/output/final_report.html")
